import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = process.argv[2]
if (!root) {
  console.error('usage: node make-fixture.mjs <superpowers plugin root>')
  process.exit(1)
}

const names = ['brainstorming', 'writing-plans', 'subagent-driven-development', 'executing-plans', 'finishing-a-development-branch']
const version = JSON.parse(readFileSync(join(root, '.claude-plugin', 'plugin.json'), 'utf8')).version
const skills = Object.fromEntries(names.map((name) => [name, readFileSync(join(root, 'skills', name, 'SKILL.md'), 'utf8')]))

const out = `// Generated by make-fixture.mjs from superpowers ${version} (MIT, see LICENSE-superpowers). Do not edit.
export const VERSION = '${version}'
export const SKILLS = ${JSON.stringify(skills, null, 2)} as const
`
// One name for every version, so an upgrade only regenerates it; the fixture test holds VERSION to PATCHED_FOR.
writeFileSync(join(dirname(fileURLToPath(import.meta.url)), 'superpowers.ts'), out)
